-- Generated by SecondKey. Review before merging: tightening access can break features
-- that rely on notes being readable or writable by other users.
alter table public."notes" enable row level security;
drop policy if exists "secondkey_select" on public."notes";
create policy "secondkey_select" on public."notes" for select using ((select auth.uid()) = "user_id");
drop policy if exists "secondkey_insert" on public."notes";
create policy "secondkey_insert" on public."notes" for insert with check ((select auth.uid()) = "user_id");
drop policy if exists "secondkey_update" on public."notes";
create policy "secondkey_update" on public."notes" for update using ((select auth.uid()) = "user_id") with check ((select auth.uid()) = "user_id");
drop policy if exists "secondkey_delete" on public."notes";
create policy "secondkey_delete" on public."notes" for delete using ((select auth.uid()) = "user_id");
